// Trazos exactos de los SVG oficiales de public/brand/ (glamluxe-*.svg) — no
// editarlos a mano: si cambia el logo, se reemplazan esos archivos y se
// regeneran estos paths. `currentColor` = color principal (GLAMLUXE); el acento
// (diamante, filetes, "by HJ") sale de --accent, así Zafiro/Azul Hielo cambian
// solos — o de --logo-accent para forzarlo sobre superficies siempre oscuras
// (`[--logo-accent:currentColor]` da la versión monocroma).
import type { SVGProps } from "react";

type LogoProps = SVGProps<SVGSVGElement> & { title?: string };

function Svg({ title = "Glam Luxe by HJ", children, ...props }: LogoProps & { viewBox: string }) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      role={title ? "img" : undefined}
      aria-label={title || undefined}
      aria-hidden={title ? undefined : true}
      {...props}
    >
      {title && <title>{title}</title>}
      {children}
    </svg>
  );
}

const ACCENT = "var(--logo-accent, var(--accent))";

